// The bootstrap compiler's recursion against the smallest stack it runs on
// (docs/modules/reserve-and-depth.md part 2): a Swift Testing or VM worker
// thread has 512 KB. Message chains are generated by loops; brackets,
// blocks, cascades, nested keyword arguments, assignments and literal
// arrays recurse, held to the parser's nesting limit, and the deepest input
// each allows compiles on a 512 KB thread in this build (debug in `swift
// test`, release in `just test-release`).

import Darwin
import Foundation
import Testing
@testable import KajoCompiler

/// The deepest input of each construct at nesting `d`.
enum NestedConstruct: String, CaseIterable, CustomTestStringConvertible {
    case parentheses, blocks, cascades, keywordArguments, assignments, literalArrays, braceArrays
    case binaryChain, unaryChain, keywordChain

    var testDescription: String { rawValue }

    func source(_ d: Int) -> String {
        func rep(_ s: String, _ n: Int) -> String { String(repeating: s, count: n) }
        switch self {
        case .parentheses: return "f ^ " + rep("(", d) + "1" + rep(")", d)
        case .blocks: return "f ^ " + rep("[", d) + "1" + rep("]", d)
        case .cascades: return "f ^ " + rep("(", d) + "1" + rep(" foo; bar)", d)
        case .keywordArguments: return "f ^ " + rep("1 k: (", d) + "1" + rep(")", d)
        case .assignments: return "f | a | ^ " + rep("a := ", d) + "1"
        case .literalArrays: return "f ^ #" + rep("(", d) + rep(")", d)
        case .braceArrays: return "f ^ " + rep("{", d) + rep("}", d)
        // Chains are not nesting: loops in the parser and code generation.
        case .binaryChain: return "f: x ^ x" + rep(" + 1", d)
        case .unaryChain: return "f: x ^ x" + rep(" yourself", d)
        case .keywordChain: return "f: x ^ " + rep("(", d) + "x" + rep(" k: 1)", d)
        }
    }

    /// The deepest the limit allows (chains: far past it).
    var deepest: Int {
        switch self {
        // A chain is bounded by the method's 32 760 bytes of bytecode.
        case .binaryChain, .unaryChain: 10_000
        // A parenthesized keyword chain nests its brackets.
        default: Parser.maxDepth
        }
    }
}

/// Run `body` on a thread of `stackBytes` and wait for it.
func onThread(stackBytes: Int, _ body: @escaping @Sendable () -> Void) {
    let done = DispatchSemaphore(value: 0)
    let t = Thread {
        body()
        done.signal()
    }
    t.stackSize = stackBytes
    t.start()
    done.wait()
}

/// The stack `body` used at most, in bytes, on an 8 MB thread: the stack
/// below the caller's frame is painted with a pattern, and after `body`
/// the deepest byte that changed is found.
func stackUsed(_ body: @escaping @Sendable () -> Void) -> Int {
    let result = UnsafeMutablePointer<Int>.allocate(capacity: 1)
    defer { result.deallocate() }
    nonisolated(unsafe) let out = result
    onThread(stackBytes: 8 << 20) {
        let top = UInt(bitPattern: pthread_get_stackaddr_np(pthread_self()))
        let low = top - UInt(pthread_get_stacksize_np(pthread_self()))
        var anchor = 0
        let sp = withUnsafeMutablePointer(to: &anchor) { UInt(bitPattern: $0) }
        let start = low + 64 << 10, end = sp - 4096
        memset(UnsafeMutableRawPointer(bitPattern: start)!, 0xA5, Int(end - start))
        body()
        let bytes = UnsafePointer<UInt8>(bitPattern: start)!
        var i = 0
        while start + UInt(i) < end && bytes[i] == 0xA5 { i += 1 }
        out.pointee = Int(sp - (start + UInt(i)))
    }
    return result.pointee
}

private func compileQuietly(_ s: String) -> Bool { (try? compile(s)) != nil }

/// The stack each construct costs per level of nesting in this build
/// (printed with KAJO_STACK_PROBE: the doc's measurements).
@Test(arguments: NestedConstruct.allCases)
func stackPerLevelOfNesting(_ c: NestedConstruct) {
    let lo = 16, hi = c.deepest
    let a = stackUsed { #expect(compileQuietly(c.source(lo))) }
    let b = stackUsed { #expect(compileQuietly(c.source(hi))) }
    let perLevel = Double(b - a) / Double(hi - lo)
    if ProcessInfo.processInfo.environment["KAJO_STACK_PROBE"] != nil {
        print("STACK \(c.rawValue): \(a) bytes at \(lo), \(b) at \(hi): \(String(format: "%.0f", perLevel)) bytes per level")
    }
    // The limit fits the smallest stack: in an optimized build with a
    // margin of four, in a debug build (frames several times larger) with
    // a quarter of it to spare.
    let margin = _isDebugAssertConfiguration() ? 1.25 : 4
    #expect(Double(b) * margin <= Double(512 << 10), "\(c): \(b) bytes at depth \(hi)")
}

/// The deepest input of every construct compiles on a 512 KB thread, and
/// one level more is refused (chains: no limit).
@Test(arguments: NestedConstruct.allCases)
func theDeepestInputCompilesOnA512KBThread(_ c: NestedConstruct) {
    onThread(stackBytes: 512 << 10) {
        #expect(compileQuietly(c.source(c.deepest)), "\(c)")
        if c.deepest == Parser.maxDepth {
            #expect(!compileQuietly(c.source(c.deepest + 1)), "\(c) past the limit")
        }
    }
}
